'use strict';
/**
 * node-addon-require-builtin —— openharmony 纯 JS 等价实现
 *
 * 原实现是预编译的 Node-API addon（按平台包分发），鸿蒙没有对应平台包，
 * 而 dsh 0.1.7 会在 host preparation 阶段硬性探测它，缺了就启动失败。
 *
 * 该 addon 的能力就是"绕过 ESM/CJS 限制去 require Node 内部模块"。
 * 当进程以 `--expose-internals` 启动时（官方桌面端就是这么启动 dsh 的：
 * ELECTRON_RUN_AS_NODE=1 + --expose-internals），普通 require 就能加载
 * internal/* 模块，因此这里用 createRequire 直接等价实现，不依赖任何原生 binding。
 */
const { createRequire } = require('node:module');

const requireFrom = createRequire(__filename);

function requireBuiltin(moduleId) {
  return requireFrom(moduleId);
}

function isAllowedInternalId(moduleId) {
  return typeof moduleId === 'string' && moduleId.length > 0;
}

function getBindingInfo() {
  const info = {
    mode: 'js-shim',
    product: 'node',
    backend: 'js',
    abi: 'napi-v9',
    bindingPath: __filename,
    bindingSource: 'js-shim',
    platform: `${process.platform}-${process.arch}`
  };
  return Object.freeze(info);
}

exports.requireBuiltin = requireBuiltin;
exports.isAllowedInternalId = isAllowedInternalId;
exports.getBindingInfo = getBindingInfo;
exports.default = { requireBuiltin, isAllowedInternalId, getBindingInfo };
